<style>
.event-command-center{container:event-command/inline-size;min-width:0;--ecc-muted:#526476;color:var(--color-ev-ink)}.event-command-center :where(h1,h2,h3,p,dd,dl,ol){margin:0}.event-command-center :where(div,section,article,aside,a){min-width:0}.event-command-center .ecc-back,.event-command-center .ecc-link{display:inline-flex;align-items:center;gap:.45rem;min-height:2.75rem;font-size:.8125rem;color:var(--color-ev-primary);font-weight:500}.event-command-center .ecc-back{margin-bottom:.65rem}.event-command-center .ecc-masthead{display:grid;grid-template-columns:minmax(0,1fr);align-items:center;gap:1rem;padding:clamp(1rem,2vw,1.5rem);border-radius:1rem;background:linear-gradient(120deg,var(--color-ev-ice),var(--color-ev-surface));border:1px solid var(--color-ev-border)}
.event-command-center .ecc-poster{container:workspace-poster/inline-size;width:7rem;max-width:100%}.event-command-center .ecc-poster .radar-poster{aspect-ratio:1;min-height:0;padding:.6rem;border-radius:.65rem;gap:.2rem}.event-command-center .ecc-poster .radar-poster-top{font-size:.5rem}.event-command-center .ecc-poster .radar-poster-top span:last-child{font-size:.5rem}.event-command-center .ecc-poster .radar-poster-type{gap:.1rem;margin:.3rem 0}.event-command-center .ecc-poster .radar-poster-type strong{font-size:clamp(.75rem,12.5cqi,1.1rem)}.event-command-center .ecc-poster .radar-poster-type>span{font-size:clamp(.625rem,9cqi,.8rem)}.event-command-center .ecc-poster .radar-poster-bottom{font-size:.4rem;gap:.3rem}.event-command-center .ecc-poster .radar-demo{font-size:.4rem;padding:.1rem .2rem;top:1.65rem;right:.6rem}.event-command-center .ecc-poster .radar-poster-orbit{width:7rem;height:7rem;right:-3rem;top:1rem}
.event-command-center h1{font-size:var(--text-ev-page);font-weight:var(--ev-heading-weight);line-height:var(--ev-heading-leading);letter-spacing:var(--ev-heading-tracking);}.event-command-center .ecc-organizer{font-size:.875rem;line-height:1.65;margin-top:.5rem}.event-command-center .ecc-metadata{display:flex;flex-wrap:wrap;align-items:center;gap:.6rem 1rem;margin-top:.65rem;font-size:.8125rem;color:var(--ecc-muted)}.event-command-center .ecc-metadata>span:not(:first-child){display:inline-flex;align-items:center;gap:.4rem}.event-command-center .ecc-header-actions{display:flex;align-items:center;flex-wrap:wrap;gap:.5rem}.event-command-center .ecc-header-actions .ev-button{display:inline-flex;align-items:center;gap:.5rem}
.event-command-center .ecc-body{display:grid;gap:2rem;align-items:start}.event-command-center .ecc-primary{display:grid;gap:1.65rem}.event-command-center .ecc-primary>section+section{border-top:1px solid var(--color-ev-border);padding-top:1.45rem}.event-command-center .ecc-section-head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:0 1rem;margin-bottom:.4rem}.event-command-center h2{font-size:var(--text-ev-section);font-weight:var(--ev-heading-weight);line-height:var(--ev-heading-leading);letter-spacing:var(--ev-heading-tracking);}.event-command-center .ecc-quiet{font-size:.875rem;line-height:1.7;color:var(--ecc-muted);padding:.65rem 0}.event-command-center .ecc-work-progress{margin-block:.5rem .85rem}.event-command-center .ecc-work-progress p{font-size:.8125rem;color:var(--ecc-muted);font-variant-numeric:tabular-nums}
.event-command-center .ecc-task-row{display:grid;grid-template-columns:1rem minmax(0,1fr);align-items:start;gap:.4rem .7rem;padding:.65rem .15rem;transition:background-color var(--ev-hover)}.event-command-center .ecc-task-row+.ecc-task-row{border-top:1px solid var(--color-ev-border)}.event-command-center .ecc-task-row:hover{background:var(--color-ev-ice)}.event-command-center .ecc-task-mark{width:.85rem;height:.85rem;border:1.5px solid #8293a0;border-radius:50%;margin-top:.3rem;display:grid;place-items:center;font-size:.55rem}.event-command-center .ecc-task-progress{border-color:var(--color-ev-info);background:var(--color-ev-info-soft)}.event-command-center .ecc-task-done{background:var(--color-ev-success);color:white;border-color:var(--color-ev-success)}.event-command-center .ecc-task-row h3{font-size:var(--text-ev-interface);font-weight:var(--ev-heading-weight);line-height:var(--ev-heading-leading);letter-spacing:var(--ev-heading-tracking);}.event-command-center .ecc-task-row p{display:flex;flex-wrap:wrap;gap:.2rem .65rem;margin-top:.2rem;font-size:.75rem;line-height:1.65;color:var(--ecc-muted)}.event-command-center .ecc-task-row time{grid-column:2;display:block;font-size:.75rem;color:var(--ecc-muted);line-height:1.6;font-variant-numeric:tabular-nums}.event-command-center .ecc-task-row time>strong{display:block;font-weight:500}.event-command-center .ecc-task-row .ecc-overdue{color:var(--color-ev-warning)}
.event-command-center .ecc-meeting-row{display:grid;grid-template-columns:3.6rem minmax(0,1fr) 1rem;align-items:center;gap:.8rem;padding:.6rem 0}.event-command-center .ecc-meeting-row+.ecc-meeting-row{border-top:1px solid var(--color-ev-border)}.event-command-center .ecc-meeting-row>time{color:var(--color-ev-info);display:grid;text-align:center;border-right:2px solid var(--color-ev-aqua);padding-right:.6rem}.event-command-center .ecc-meeting-row>time strong{font-size:1.25rem;font-weight:var(--font-weight-semibold);line-height:1.3}.event-command-center .ecc-meeting-row>time span{font-size:var(--text-ev-metadata);color:var(--ecc-muted)}.event-command-center .ecc-meeting-row h3{font-size:var(--text-ev-card);font-weight:var(--ev-heading-weight);line-height:var(--ev-heading-leading);letter-spacing:var(--ev-heading-tracking);}.event-command-center .ecc-meeting-row p{font-size:.75rem;line-height:1.65;color:var(--ecc-muted);margin-top:.25rem}.event-command-center .ecc-meeting-row>svg{color:var(--color-ev-primary)}
.event-command-center .ecc-context-panel{display:grid;gap:1.4rem}.event-command-center .ecc-context-panel h2{font-size:var(--text-ev-section);font-weight:var(--ev-heading-weight);line-height:var(--ev-heading-leading);letter-spacing:var(--ev-heading-tracking);}.event-command-center .ecc-team{padding:1rem;border:1px solid var(--color-ev-border);border-radius:.75rem;background:var(--color-ev-surface)}.event-command-center .ecc-team .ecc-section-head{margin-bottom:.4rem}.event-command-center .ecc-team-lead{display:flex;align-items:center;gap:.65rem;padding:.5rem 0}.event-command-center .ecc-team-lead>span{display:grid;place-items:center;flex:none;width:2.5rem;height:2.5rem;border-radius:50%;background:var(--color-ev-mist);color:var(--color-ev-primary)}.event-command-center .ecc-team-lead strong{font-size:.8125rem;font-weight:var(--font-weight-semibold);line-height:1.6}.event-command-center .ecc-team-lead p{font-size:.75rem;color:var(--ecc-muted);margin-top:.15rem}.event-command-center .ecc-series{padding-inline:.2rem}.event-command-center .ecc-series ol{list-style:none;padding:0;margin-top:.6rem}.event-command-center .ecc-series li{border-left:2px solid var(--color-ev-border);padding:.2rem 0 .45rem .75rem}.event-command-center .ecc-series li[aria-current]{border-color:var(--color-ev-primary)}.event-command-center .ecc-series li strong{display:block;font-size:.875rem;font-weight:var(--font-weight-semibold);line-height:1.6}.event-command-center .ecc-series li span{display:block;color:var(--ecc-muted);font-size:.75rem;margin-bottom:.15rem}
.event-command-center .ecc-facts{border-top:1px solid var(--color-ev-border)}.event-command-center .ecc-facts summary{display:flex;align-items:center;justify-content:space-between;gap:.65rem;min-height:2.75rem;cursor:pointer;font-size:.8125rem;font-weight:600;list-style:none}.event-command-center .ecc-facts summary::-webkit-details-marker{display:none}.event-command-center .ecc-facts[open] summary svg{transform:rotate(180deg)}.event-command-center .ecc-facts dl{display:grid;gap:.8rem;padding:.4rem 0 1rem}.event-command-center .ecc-facts dt{font-size:.75rem;color:var(--ecc-muted)}.event-command-center .ecc-facts dd{font-size:.8125rem;line-height:1.7;margin-top:.2rem;white-space:pre-line}.event-command-center .ecc-cancel{font-size:.75rem;color:var(--color-ev-danger);min-height:2.75rem;display:inline-flex;align-items:center}
.event-command-center .ecc-lesson{padding:.7rem 0}.event-command-center .ecc-lesson+.ecc-lesson{border-top:1px solid var(--color-ev-border)}.event-command-center .ecc-lesson h3{max-width:70ch;font-size:var(--text-ev-card);font-weight:var(--ev-heading-weight);line-height:var(--ev-heading-leading);letter-spacing:var(--ev-heading-tracking);}.event-command-center .ecc-recommendation,.event-command-center .ecc-decision{margin-top:.4rem;font-size:.875rem;line-height:1.65;max-width:70ch;color:var(--ecc-muted)}.event-command-center .ecc-decision strong{margin-inline-end:.35rem;color:var(--color-ev-ink);font-weight:600}
@container event-command (min-width:35rem){.event-command-center .ecc-poster{width:8.5rem}.event-command-center .ecc-masthead{grid-template-columns:8.5rem minmax(0,1fr)}.event-command-center .ecc-header-actions{grid-column:2}.event-command-center .ecc-task-row{grid-template-columns:1rem minmax(0,1fr) auto;align-items:center}.event-command-center .ecc-task-row time{grid-column:3;grid-row:1;text-align:right}}
@container event-command (min-width:58rem){.event-command-center .ecc-masthead{grid-template-columns:8.5rem minmax(0,1fr) auto}.event-command-center .ecc-header-actions{grid-column:3;flex-direction:column;align-items:stretch}.event-command-center .ecc-body{grid-template-columns:minmax(0,2fr) minmax(15rem,.9fr);gap:clamp(1.75rem,3vw,3rem)}}
